<template>
  <div class="itinerary-layout">
    <nav class="journey-days" aria-label="整趟日期导航"><button v-for="(date,i) in journeyDates" :key="date" :class="{selected:currentWindow?.date===date}" :aria-pressed="currentWindow?.date===date" @click="selectJourneyDate(date)"><small>第 {{i+1}} 天 · {{weekday(date)}}</small><strong>{{shortDate(date)}}</strong><span>{{citiesForDate(date).map(c=>c.city).join(' → ')}}</span></button></nav>
    <nav class="city-list" aria-label="选择城市行程">
      <span class="chapter-label">沿途 / DESTINATIONS</span>
      <button v-for="(city,i) in cities" :key="city.id" :class="{selected:currentCity?.id===city.id}" :aria-pressed="currentCity?.id===city.id" @click="selectCity(city.id)">
        <span class="city-index">0{{i+1}}</span><span class="city-label"><strong>{{city.city}}</strong><small>{{city.nights}} 晚 · {{city.windows.length}} 天</small></span><span aria-hidden="true">↗</span>
      </button>
      <p class="chapter-note">城市之间，随心切换。<span>城市内日期可单独切换</span></p>
    </nav>
    <section v-if="currentCity" class="city-detail" :aria-label="currentCity.city+'的每日安排'">
      <div class="city-title"><div><span class="eyebrow">{{String(cities.findIndex(c=>c.id===currentCity.id)+1).padStart(2,'0')}} / 城市日程</span><h3>{{currentCity.city}}<span>此刻，想去哪里</span></h3></div><span class="badge">{{currentCity.source_draft?'已有城市安排':'待安排景点'}}</span></div>
      <p v-if="currentCity.stale" class="warning">日期或人数变化，旧安排已保留，费用暂不计入；请重新选择景点。</p>
      <div class="day-picker" aria-label="选择日期">
        <button v-for="w in currentCity.windows" :key="w.date" :class="{selected:currentWindow?.date===w.date}" :aria-pressed="currentWindow?.date===w.date" @click="selectedDate=w.date"><small>{{weekday(w.date)}}</small><strong>{{shortDate(w.date)}}</strong><span>{{dateLabel(w)}}</span></button>
      </div>
      <Transition name="day-page" mode="out-in" appear>
      <div v-if="currentWindow" :key="currentCity.id+currentWindow.date" class="day-content">
        <div class="day-heading"><div><span class="eyebrow">{{currentWindow.date}}</span><h4>{{dayTitle}}</h4></div><span class="window-note">{{windowText(currentWindow)}}</span></div>
        <p v-if="rhythmItems.length" class="actual-start">当天 {{rhythmStart}} 开始安排 · {{rhythmEnd}} 结束</p>
        <div v-if="dayTransfers.length" class="day-transfers" aria-label="当天城际衔接"><article v-for="transfer in dayTransfers" :key="transfer.from_stop+'-'+transfer.to_stop"><small>当天交通 · {{transfer.leg?.booking_status==='booked'?'已订':'计划中'}}</small><strong>{{transfer.from_city}} → {{transfer.to_city}} · {{transfer.leg?.service_number || '班次待选'}}</strong><p v-if="transfer.leg">{{transfer.leg.departure_time.replace('T',' ')}} {{transfer.leg.departure_station}} → {{transfer.leg.arrival_time.replace('T',' ')}} {{transfer.leg.arrival_station}}</p><p v-else>先确认班次，再安排两侧的游览与用餐。</p><div class="day-transfer-actions"><button @click="$emit('transport',transfer.from_stop,transfer.to_stop)">查看本段衔接 →</button><button v-for="city in citiesForDate(currentWindow.date).filter(c=>c.id!==currentCity.id)" :key="city.id" @click="selectCity(city.id,true)">查看 {{city.city}} 同一天 →</button></div></article></div>
        <div v-if="rhythmItems.length" class="day-rhythm" aria-label="全天节奏，点击定位安排">
          <div class="rhythm-caption"><span>一天的节奏</span><small>点击色块，定位安排</small></div>
          <div class="rhythm-track"><button v-for="entry in rhythmItems" :key="entry.index" :class="['rhythm-'+entry.item.kind,{highlighted:highlightedIndex===entry.index}]" :style="entry.style" :aria-label="entry.item.start_time+'至'+entry.item.end_time+' '+(entry.item.ref_name||kindLabel(entry.item.kind))" :title="entry.item.start_time+'—'+entry.item.end_time+' '+(entry.item.ref_name||kindLabel(entry.item.kind))" @click="focusActivity(entry.index)"></button></div>
          <div class="rhythm-scale"><span>{{rhythmStart}}</span><span>游览 <i class="legend-visit"></i> 用餐 <i class="legend-meal"></i> 路程与其他 <i class="legend-other"></i></span><span>{{rhythmEnd}}</span></div>
        </div>
        <div v-if="currentDay?.timeline_schedule?.length" class="day-lens"><span>{{dayCounts}}</span><button v-if="transitCount" :aria-pressed="showConnections" @click="showConnections=!showConnections;highlightedIndex=-1">{{showConnections?'收起路程细节':'展开完整时间轴'}} <span aria-hidden="true">{{showConnections?'−':'＋'}}</span></button></div>
        <p v-if="transitCount && !showConnections" class="connection-hint">已收起 {{transitCount}} 段路程、等候或空档，时间已保留在安排中。</p>
        <div class="day-spread"><div ref="timelinePanel" class="day-main">
        <p v-if="currentWindow.provisional" class="muted">交通尚未填齐，可用时段暂定。<template v-if="!readonly">先确定抵离时间，可以减少换城日的重复调整。 <button class="transport-shortcut" @click="$emit('transport')">先安排交通 →</button></template></p>
        <p v-if="currentWindow.moving" class="muted">今天需要移动，先留出赶车、行李和用餐时间。</p>

        <TransitionGroup v-if="currentDay?.timeline_schedule?.length" tag="ol" name="timeline-step" class="timeline">
          <li v-for="(item,i) in visibleTimeline" :key="itemIndex(item)" :style="{'--item-order':Math.min(i,5)}" :class="['kind-'+item.kind,{highlighted:highlightedIndex===itemIndex(item)}]" :data-index="itemIndex(item)" tabindex="-1"><time>{{isHotelReference(item)?"位置":item.start_time}}<small>{{isHotelReference(item)?"参考":item.end_time}}</small></time><span class="timeline-dot" aria-hidden="true"></span><div><small>{{isHotelReference(item)?"酒店位置，不代表入住时间":kindLabel(item.kind)}}</small><button class="activity-open" :aria-expanded="selectedActivity===itemIndex(item)" @click="selectedActivity=selectedActivity===itemIndex(item)?-1:itemIndex(item)">{{item.ref_name || item.description || '行程安排'}} <span>↗</span></button><div v-if="selectedActivity===itemIndex(item)" class="activity-detail"><p>{{item.detail || item.description || '时间来自已保存安排；修改后需要重新核对路线与当天衔接。'}}</p><p v-if="item.kind==='travel' && /轮渡|渡轮|码头.*码头/.test(item.detail || '')">含轮渡的路程是地图预计；实际船班、候船和停航情况请出发前核对。</p><button v-if="!readonly" :disabled="disabled" @click="$emit('edit-day',{id:currentCity.id,date:currentWindow.date})">在当天行程中编辑 →</button></div><span v-if="itemMinutes(item)>0" class="item-duration">{{itemMinutes(item)}} 分钟</span></div></li>
        </TransitionGroup>
        <div v-else class="empty-day"><span class="empty-mark" aria-hidden="true">＋</span><h4>{{currentWindow.available_minutes===0?'给移动和休息留点空间':'这一天，留给你喜欢的风景'}}</h4><p>{{currentWindow.available_minutes===0?'当前没有可安排游玩的时间，仍请核对住宿与正餐。':'还没有同步每日安排。从喜欢的景点开始，逐步补齐用餐和路线。'}}</p></div>
        </div><aside class="day-aside" aria-label="当天住宿与提醒">
        <figure v-if="dayPhoto && !photoFailed" class="day-photo"><img :src="dayPhoto" :alt="dayTitle+'的景点图片'" loading="lazy" referrerpolicy="no-referrer" @error="photoFailed=true" /><figcaption>{{dayTitle}}<span>景点资料图</span></figcaption></figure>
        <div v-if="currentWindow.rest_periods?.length" class="rest-note"><strong>留给自己的时间</strong><p v-for="r in currentWindow.rest_periods" :key="r.id">{{r.start_time}}—{{r.end_time}} · {{r.label}}</p><small>休息落实情况以每日时间轴为准。</small></div>
        <div class="hotel-note"><span aria-hidden="true">⌂</span><div><small>每日酒店</small><strong>{{currentDay?.hotel?.name || '尚未安排'}}</strong><p>整趟手动住宿区间优先计费，请在费用与待办中核对。</p></div></div>
        <details v-if="currentDay?.description" class="day-description"><summary>当天节奏与提醒<span>展开阅读安排说明</span></summary><p>{{currentDay.description}}</p></details>
        </aside></div>
      </div>
      <p v-else key="no-window" class="empty-day">还没有可展示的每日时间窗口，先核对城市日期。</p>
      </Transition>
      <div v-if="!readonly" class="city-actions"><button v-if="currentCity.source_draft&&!currentCity.stale" class="primary" :disabled="disabled" @click="$emit('edit',currentCity.id)">继续编辑每日安排 →</button><button :class="{primary:!currentCity.source_draft}" :disabled="disabled" @click="$emit('plan',currentCity.id)">{{currentCity.source_draft?'重新选择景点':'选择景点并安排这座城市'}}{{currentCity.source_draft?'':' →'}}</button></div>
    </section>
    <div v-else class="empty-day">还没有城市安排，请先填写城市与日期。</div>
  </div>
</template>
<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue'
const props=defineProps<{cities:any[];readonly:boolean;disabled:boolean;focusCity?:string;focusDate?:string;transfers?:any[]}>()
const emit=defineEmits<{(e:'plan',id:string):void;(e:'edit',id:string):void;(e:'transport',from?:string,to?:string):void;(e:'city-change',id:string):void;(e:'edit-day',value:{id:string;date:string}):void}>()
const selectedActivity=ref(-1)
const selectedCity=ref(''),selectedDate=ref(''),showConnections=ref(false)
const currentCity=computed(()=>props.cities.find(c=>c.id===selectedCity.value)||props.cities[0])
const currentWindow=computed(()=>currentCity.value?.windows.find((w:any)=>w.date===selectedDate.value)||currentCity.value?.windows[0])
const currentDay=computed(()=>currentCity.value?.days.find((d:any)=>d?.date===currentWindow.value?.date))
const journeyDates=computed(()=>[...new Set<string>(props.cities.flatMap(c=>c.windows.map((w:any)=>w.date)))].sort())
const citiesForDate=(date:string)=>props.cities.filter(c=>c.windows.some((w:any)=>w.date===date))
const dayTransfers=computed(()=>(props.transfers||[]).filter(t=>t.leg?.departure_time?.slice(0,10)===currentWindow.value?.date || t.leg?.arrival_time?.slice(0,10)===currentWindow.value?.date))
function selectJourneyDate(date:string){const city=citiesForDate(date).find(c=>c.id===selectedCity.value)||citiesForDate(date)[0];if(city){selectedCity.value=city.id;selectedDate.value=date;emit('city-change',city.id)}}
function dateLabel(w:any){if(w.moving){if(w.date===journeyDates.value[0])return '出发日';if(w.date===journeyDates.value.at(-1))return '返程日';return '换城日'}return w.rest_minutes?'含休息':'自由探索'}
const timelinePanel=ref<HTMLElement|null>(null),highlightedIndex=ref(-1)
const minuteOf=(time:string)=>{const [h,m]=time.split(':').map(Number);return (h||0)*60+(m||0)}
const isHotelReference=(item:any)=>item.kind==='hotel' && item.start_time===item.end_time
const itemIndex=(item:any)=>(currentDay.value?.timeline_schedule||[]).indexOf(item)
const rhythmStart=computed(()=>currentDay.value?.timeline_schedule?.[0]?.start_time||'08:00')
const rhythmEnd=computed(()=>currentDay.value?.timeline_schedule?.at(-1)?.end_time||'22:00')
const rhythmItems=computed(()=>{const start=minuteOf(rhythmStart.value),span=Math.max(1,minuteOf(rhythmEnd.value)-start);return (currentDay.value?.timeline_schedule||[]).map((item:any,index:number)=>({item,index,style:{left:`${Math.max(0,(minuteOf(item.start_time)-start)/span*100)}%`,width:`${Math.max(0,(minuteOf(item.end_time)-minuteOf(item.start_time))/span*100)}%`}})).filter((e:any)=>minuteOf(e.item.end_time)>minuteOf(e.item.start_time))})
async function focusActivity(index:number){const item=currentDay.value?.timeline_schedule?.[index];if(!item)return;if(connectionKinds.has(item.kind))showConnections.value=true;highlightedIndex.value=index;await nextTick();const row=timelinePanel.value?.querySelector<HTMLElement>(`[data-index="${index}"]`);row?.focus({preventScroll:true});row?.scrollIntoView?.({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'})}
watch(()=>currentWindow.value?.date,()=>{highlightedIndex.value=-1;selectedActivity.value=-1})
const connectionKinds=new Set(['transport','route','travel','wait','free_time','free','gap'])
const transitCount=computed(()=>currentDay.value?.timeline_schedule?.filter((i:any)=>connectionKinds.has(i.kind)).length||0)
const visibleTimeline=computed(()=>(currentDay.value?.timeline_schedule||[]).filter((i:any)=>showConnections.value||!connectionKinds.has(i.kind)))
const dayTitle=computed(()=>currentDay.value?.timeline_schedule?.find((i:any)=>i.kind==='attraction')?.ref_name || (currentWindow.value?.moving?'抵达与启程，也从容一些':'把这一天，留给自己'))
const photoFailed=ref(false)
const dayPhoto=computed(()=>{const source=currentDay.value?.attractions?.find((a:any)=>a.name===dayTitle.value)?.image_url;return typeof source==='string'&&/^https?:\/\//.test(source)?source:''})
watch(dayPhoto,()=>{photoFailed.value=false})
const dayCounts=computed(()=>{const items=currentDay.value?.timeline_schedule||[];return `${items.filter((i:any)=>i.kind==='attraction').length} 处游览 · ${items.filter((i:any)=>i.kind==='meal').length} 餐安排`})
const weekday=(date:string)=>new Intl.DateTimeFormat('zh-CN',{weekday:'short',timeZone:'UTC'}).format(new Date(date+'T00:00:00Z'))
const itemMinutes=(item:any)=>{const minutes=(t:string)=>{const [h,m]=t.split(':').map(Number);return (h||0)*60+(m||0)};return Math.max(0,minutes(item.end_time)-minutes(item.start_time))}
function selectCity(id:string,keepDate=false){const date=currentWindow.value?.date;selectedCity.value=id;selectedDate.value=keepDate?date:'';emit('city-change',id)}
watch(()=>props.focusCity,id=>{if(id && id!==selectedCity.value)selectCity(id)},{immediate:true})
watch(()=>props.focusDate,date=>{if(date)selectJourneyDate(date)},{immediate:true})
const shortDate=(date:string)=>`${Number(date.slice(5,7))}月${Number(date.slice(8,10))}日`
const clock=(n:number)=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')
const windowText=(w:any)=>w.available_minutes===0?'暂无游玩时段':`${clock(Math.max(480,w.start_minutes))}—${clock(Math.min(1320,w.end_minutes))} 可安排活动`
const kindLabel=(kind:string)=>({attraction:'游览',meal:'用餐',transport:'路上',route:'路上',travel:'路上',wait:'等候',free_time:'未安排时间',rest:'休息',hotel:'住宿',free:'自由时间',gap:'未安排时间'}[kind]||'行程')
</script>
<style scoped>
