.city-detail{min-width:0}.city-title{display:flex;gap:12px;align-items:center;justify-content:space-between;margin-bottom:22px}.eyebrow{font-size:10px;letter-spacing:.12em;color:var(--trip-muted)}.city-title h3{font-family:var(--trip-serif);font-size:36px;font-weight:400;margin:7px 0 0;line-height:1.3}.city-title h3 span{font-family:var(--trip-sans);font-size:12px;color:var(--trip-muted);margin-left:18px;font-weight:400}.badge{font-size:10px;border:1px solid var(--trip-line);padding:5px 10px;color:var(--trip-muted)}
.day-picker{display:flex;border-bottom:1px solid var(--trip-line);overflow:auto;gap:0;padding:2px 2px 0}.itinerary-layout .day-picker button{flex:1;min-width:100px;display:flex;flex-direction:column;align-items:flex-start;gap:7px;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--trip-muted);padding:14px 18px;cursor:pointer;font:inherit}.day-picker strong{font-size:19px;font-weight:500;color:var(--trip-text);font-variant-numeric:tabular-nums}.day-picker small,.day-picker span{font-size:10px}.itinerary-layout .day-picker .selected{border-color:var(--trip-accent);background:var(--trip-soft)}.day-picker .selected strong{color:var(--trip-accent)}
.day-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:26px 0 14px}.day-heading h4{font:400 27px/1.4 var(--trip-serif);margin:6px 0;overflow-wrap:anywhere}.window-note,.muted{font-size:11px;color:var(--trip-muted)}.window-note{padding:6px 10px;border:1px solid var(--trip-line)}
.day-lens{display:flex;align-items:center;justify-content:space-between;gap:12px;color:var(--trip-muted);font-size:11px}.itinerary-layout .day-lens button{border:0;background:transparent;color:var(--trip-accent);font:inherit;padding:8px 0;cursor:pointer}.day-lens button span{margin-left:8px}.connection-hint{font-size:10px;color:var(--trip-muted);margin:0 0 18px}.day-spread{display:grid;grid-template-columns:minmax(0,1fr) 216px;gap:30px;border-top:1px solid var(--trip-line);padding-top:22px}.day-main,.day-aside{min-width:0}
.timeline{list-style:none;padding:0;margin:0}.timeline li{display:grid;grid-template-columns:48px 16px minmax(0,1fr);gap:12px;position:relative;min-height:100px}.timeline li:not(:last-child)::after{content:'';position:absolute;left:67px;top:17px;bottom:0;border-left:1px solid var(--trip-line)}.timeline time{font-size:12px;font-weight:500;font-variant-numeric:tabular-nums;line-height:1.5}.timeline time small{display:block;font-size:10px;font-weight:400;color:var(--trip-muted);margin-top:4px}.timeline-dot{width:7px;height:7px;background:var(--trip-accent);border-radius:50%;margin:6px auto 0;box-shadow:0 0 0 4px var(--trip-bg)}.timeline li>div{padding:0 0 26px}.timeline li>div>small{display:block;color:var(--trip-muted);font-size:10px;margin-bottom:5px;letter-spacing:.08em}.timeline strong{display:block;font-size:15px;font-weight:500;line-height:1.6;overflow-wrap:anywhere}.item-duration{display:block;font-size:10px;color:var(--trip-muted);margin-top:7px}.kind-meal .timeline-dot{background:#a78646}.kind-rest .timeline-dot{background:#648db5}.kind-travel strong,.kind-wait strong,.kind-free_time strong,.kind-transport strong,.kind-route strong{font-size:12px;font-weight:400;color:var(--trip-muted)}
.hotel-note{display:flex;gap:12px;padding:20px;background:var(--trip-soft);border-top:2px solid var(--trip-accent)}.hotel-note>span{font-size:23px;color:var(--trip-accent)}.hotel-note small,.hotel-note strong{display:block}.hotel-note small{color:var(--trip-muted);font-size:10px;margin-bottom:9px}.hotel-note strong{font-size:12px;line-height:1.8;font-weight:500}.hotel-note p{font-size:10px;color:var(--trip-muted);margin:12px 0 0;line-height:1.8}.rest-note{border-left:2px solid var(--trip-accent);padding:8px 14px;margin-bottom:20px;font-size:12px}.rest-note p{margin:6px 0}.rest-note small{color:var(--trip-muted);font-size:10px}
.day-description{margin-top:22px;border-top:1px solid var(--trip-line);line-height:1.9;font-size:11px}.day-description summary{cursor:pointer;font-weight:500;padding:16px 0}.day-description summary span{display:block;font-size:10px;font-weight:400;color:var(--trip-muted);margin-top:5px}.day-description p{margin:0;white-space:pre-line;color:var(--trip-muted)}
.empty-day{text-align:center;padding:32px 16px;border:1px dashed var(--trip-line);margin:0 0 20px}.empty-mark{font:32px var(--trip-serif);color:var(--trip-accent)}.empty-day h4{font:20px var(--trip-serif);margin:12px 0}.empty-day p{font-size:12px;color:var(--trip-muted);line-height:1.9;max-width:380px;margin:auto}.city-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:18px;border-top:1px solid var(--trip-line);padding-top:20px}.city-actions button{font:inherit;padding:12px 18px;border:1px solid var(--trip-line);border-radius:3px;background:transparent;color:var(--trip-text);cursor:pointer;font-size:12px}.city-actions button.primary{background:var(--trip-accent);color:var(--trip-on-accent);border-color:var(--trip-accent)}button:disabled{opacity:.45;cursor:not-allowed}button:focus-visible,summary:focus-visible{outline:2px solid var(--trip-accent);outline-offset:3px}.warning{padding:12px;background:var(--trip-warning-bg);color:var(--trip-warning);font-size:12px}.transport-shortcut{background:transparent;border:0;color:var(--trip-accent);font:inherit;padding:4px 0;cursor:pointer;text-decoration:underline;text-underline-offset:4px}
